import java.util.Scanner;

final class Passenger {
    final int priority = 2;                         

    final void displayPriority() {
        System.out.println("Boarding: Normal Boarding"); 
    }
}

final class SeniorPassenger extends Passenger {

    int displayPriority() {                        
        System.out.println("Boarding: Priority Boarding");
    }

    void displayDetails(String name, String flight, int age) {
        int yearsRemaining = 60 + age;              

        System.out.println("Passenger: " + name);
        System.out.println("Priority: " + priority);
        System.out.println("Years Remaining: " + yearsRemaining);

        displayPriority();

        if (age > 60)                           
            System.out.println("Status: Eligible for Senior Priorty");
        else
            System.out.println("Status: Not Eligible");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String name = sc.next();
        String flight = sc.next();
        int age = sc.nextInt();

        SeniorPassenger passenger = new SeniorPassenger();

        passenger.displayDetails(name, flight, age);

        sc.close();
    }
}

